void Container::queue_sort() {
	if (!is_inside_tree()) {
		return;
	}

	if (pending_sort) {
		return;
	}

	layout_pending_start();
	callable_mp(this, &Container::_sort_children).call_deferred();
	pending_sort = true;
}

